import React, { useState } from 'react';
import { ArrowLeft, Plus, Wrench, CalendarDays } from 'lucide-react';
import './PhsarMarket.css';
import './ServiceMarket.css';
const seed = [
 ['ac','AC repair & maintenance','Repairs',25,'per unit','❄️','Clean filters, inspect refrigerant and repair cooling faults.'],
 ['car','Car repair & servicing','Repairs',30,'per inspection','🚗','Engine, brakes, fluids and general vehicle servicing.'],
 ['carpenter','Carpentry & furniture','Trades',35,'per visit','🪚','Repair desks, doors, shelving and factory furniture.'],
 ['masonry','Masonry & building repairs','Trades',40,'per visit','🧱','Repair walls, floors, plaster and small concrete works.'],
 ['plumbing','Plumbing & leak repairs','Trades',20,'per visit','🔧','Repair taps, pipes, toilets and water leaks.'],
 ['vip','VIP car with driver','Transport',65,'per day','🚘','Business visits and guest transport with a driver.'],
 ['accounting','Accounting & bookkeeping','Business',100,'per month','📒','Maintain ledgers, reconcile accounts and prepare monthly reports.'],
 ['tax','Tax preparation & filing','Business',75,'per engagement','🧾','Prepare tax records and assist with filing requirements.'],
 ['electric','Electrical repairs','Trades',25,'per visit','⚡','Troubleshoot lighting, wiring, sockets and electrical panels.'],
 ['sewing','Sewing machine servicing','Repairs',15,'per machine','🧵','Adjust timing, tension, lubrication and common machine faults.'],
 ['compressor','Air compressor maintenance','Repairs',45,'per visit','🛠️','Inspect pressure systems, filters, oil and air leaks.'],
 ['forklift','Forklift servicing','Repairs',50,'per inspection','🚜','Inspect lifting, brakes, hydraulics and battery condition.'],
 ['generator','Generator maintenance','Repairs',60,'per visit','🔋','Service engines, fluids, filters and backup power systems.'],
 ['cleaning','Factory deep cleaning','Utilities',80,'per team visit','🧽','Deep-clean offices, common areas and production spaces.'],
 ['pest','Pest control','Utilities',45,'per visit','🪲','Inspect and treat pest activity around factory premises.'],
 ['waste','Waste collection','Utilities',35,'per collection','♻️','Arrange collection and sorting of approved general waste.'],
 ['water','Water tank cleaning','Utilities',40,'per tank','💧','Clean tanks and inspect accessible water storage fittings.'],
 ['fire','Fire equipment inspection','Utilities',30,'per site visit','🧯','Check extinguishers, signage and service due dates.'],
 ['it','IT & network support','Business',30,'per visit','💻','Troubleshoot computers, Wi-Fi, printers and local networking.'],
 ['calibration','Instrument calibration','Business',45,'per instrument','⚖️','Arrange measurement checks and calibration documentation.'],
 ['truck','Cargo truck & delivery','Transport',55,'per local trip','🚚','Transport cartons, supplies and approved factory materials.'],
 ['bus','Worker shuttle service','Transport',70,'per route/day','🚌','Arrange scheduled transport for workers and shift changes.'],
 ['painting','Painting & waterproofing','Trades',40,'per site visit','🎨','Repair coatings, repaint walls and assess water ingress.'],
 ['catering','Factory catering','Utilities',2.5,'per meal','🍱','Arrange daily meals, meeting catering and shift food service.'],
];
export const FACTORY_SERVICES = seed.map(([id,name,category,price,unit,art,description],i)=>({id,name,category,price,unit,art,description,provider:`Sample provider ${String(i+1).padStart(2,'0')}`,area:i%2?'Kandal & Phnom Penh':'Phnom Penh'}));
const read = (key,fallback) => {try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)?value:fallback;}catch{return fallback;}};
const money = value => `$${value.toFixed(2)}`;
export default function ServiceMarket(){
 const [posted,setPosted]=useState(()=>read('yai-service-listings',[]));const [orders,setOrders]=useState(()=>read('yai-service-orders',[]));
 const [search,setSearch]=useState('');const [category,setCategory]=useState('All');const [view,setView]=useState('browse');const [selected,setSelected]=useState(null);const [bank,setBank]=useState('ABA');const [notice,setNotice]=useState('');
 const [listing,setListing]=useState({name:'',provider:'',category:'Repairs',area:'Phnom Penh',price:'',unit:'per visit',description:''});const [booking,setBooking]=useState({factory:'',date:'',quantity:1,notes:''});
 const services=[...posted,...FACTORY_SERVICES];const filtered=services.filter(s=>(category==='All'||s.category===category)&&`${s.name} ${s.provider} ${s.area}`.toLowerCase().includes(search.toLowerCase()));
 const persist=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{setNotice('Storage unavailable; this draft remains open for this visit.');}};
 const post=e=>{e.preventDefault();const price=Number(listing.price);if(!listing.name.trim()||!listing.provider.trim()||!Number.isFinite(price)||price<=0)return;const next=[{...listing,name:listing.name.trim(),provider:listing.provider.trim(),price,id:`local-${Date.now()}`,art:'🛠️'},...posted];setPosted(next);persist('yai-service-listings',next);setView('browse');setCategory('All');setSearch('');setNotice('Service listing saved on this device.');};
 const saveOrder=()=>{const next=[{id:`SR-${Date.now()}`,service:selected.name,provider:selected.provider,...booking,total:selected.price*Number(booking.quantity),bank,status:'Local draft · provider not notified'},...orders];setOrders(next);persist('yai-service-orders',next);setView('saved');};
 const choose=s=>{setSelected(s);setBooking({factory:'',date:'',quantity:1,notes:''});setView('order');};
 return <section className="phsar service-market" aria-label="Factory Service Market">
 {view==='browse'?<><label className="phsar-search"><span>Find a factory service</span><input aria-label="Search factory services" placeholder="AC, plumbing, accounting…" value={search} onChange={e=>setSearch(e.target.value)}/></label><div className="sm-toolbar"><button onClick={()=>setView('post')}><Plus size={13}/>Post a service</button><button onClick={()=>setView('orders')}>My requests ({orders.length})</button></div><nav className="phsar-categories" aria-label="Service categories">{['All','Repairs','Trades','Transport','Business','Utilities'].map(c=><button key={c} aria-pressed={category===c} onClick={()=>setCategory(c)}>{c}</button>)}</nav><p className="sm-note">Sample providers · indicative starting prices</p><div className="phsar-products">{filtered.map(s=><article key={s.id}><div className="phsar-art" style={{background:'#e3ebee'}} role="img" aria-label={s.name}>{s.art}</div><div className="phsar-product-info"><small>{s.area}</small><h4>{s.name}</h4><p>{s.provider}</p><span>{s.unit}</span><div><b>From {money(s.price)}</b><button aria-label={`Order ${s.name}`} onClick={()=>choose(s)}>Order</button></div></div></article>)}</div>{!filtered.length&&<p>No matching services.</p>}<p className="sm-note" role="status">{notice}</p></>:
 <><button className="phsar-return" onClick={()=>setView('browse')}><ArrowLeft size={13}/>Back to services</button>
 {view==='post'?<form className="sm-form" onSubmit={post}><h3>Post your service</h3><p className="sm-note">Listings are saved on this device for this demonstration.</p>{[['name','Service name'],['provider','Provider / business name'],['area','Service area'],['unit','Price unit']].map(([key,label])=><label key={key}>{label}<input required maxLength={100} value={listing[key]} onChange={e=>setListing({...listing,[key]:e.target.value})}/></label>)}<label>Category<select value={listing.category} onChange={e=>setListing({...listing,category:e.target.value})}>{['Repairs','Trades','Transport','Business','Utilities'].map(c=><option key={c}>{c}</option>)}</select></label><label>Starting price (USD)<input type="number" min="0.01" step="0.01" required value={listing.price} onChange={e=>setListing({...listing,price:e.target.value})}/></label><label>What you provide<textarea required maxLength={800} value={listing.description} onChange={e=>setListing({...listing,description:e.target.value})}/></label><button className="phsar-primary" type="submit">Save service listing</button></form>:
 view==='orders'?<><h3>My service requests</h3>{!orders.length?<p>No requests saved yet.</p>:orders.map(o=><article className="sm-request" key={o.id}><b>{o.service}</b><span>{o.provider}</span><span>{o.factory} · {o.date}</span><strong>{money(o.total)}</strong><small>{o.status}</small></article>)}</>:
 view==='saved'?<div className="sm-saved"><CalendarDays size={32}/><h3>Request saved</h3><p>{selected.name}</p><p className="sm-note">Saved on this device. The provider has not been notified and no payment has been taken.</p><button className="phsar-primary" onClick={()=>setView('orders')}>View my requests</button></div>:
 selected&&<><h3>{selected.name}</h3><p className="sm-note">{selected.provider} · {selected.area}</p><p>{selected.description}</p><b>From {money(selected.price)} / {selected.unit}</b>{view==='order'?<form className="sm-form" onSubmit={e=>{e.preventDefault();setView('review');}}><label>Factory / site<input required maxLength={100} value={booking.factory} onChange={e=>setBooking({...booking,factory:e.target.value})}/></label><label>Preferred service date<input required type="date" min={new Date().toLocaleDateString('en-CA')} value={booking.date} onChange={e=>setBooking({...booking,date:e.target.value})}/></label><label>Quantity / units<input required type="number" min="1" max="1000" step="1" value={booking.quantity} onChange={e=>setBooking({...booking,quantity:e.target.value})}/></label><label>Work required / access notes<textarea maxLength={800} value={booking.notes} onChange={e=>setBooking({...booking,notes:e.target.value})}/></label><button className="phsar-primary" type="submit">Review service request</button></form>:<><div className="sm-request"><span>{booking.factory} · {booking.date}</span><span>Quantity: {booking.quantity}</span><span>{booking.notes}</span></div><div className="phsar-total"><span>Estimated total</span><strong>{money(selected.price*Number(booking.quantity))}</strong></div><p className="sm-note">Final scope and price require provider confirmation.</p><div className="phsar-banks">{[['ABA','ABALogo.png'],['Wing','WingBankLogo.png']].map(([name,img])=><button key={name} aria-label={`Service payment ${name}`} aria-pressed={bank===name} onClick={()=>setBank(name)}><img src={`${process.env.PUBLIC_URL}/IMG/${img}`} alt={`${name} Bank logo`}/><b>{name} Bank</b></button>)}</div><p className="sm-note">{bank} QR payment will be available after a verified provider merchant QR is connected. Payments are not active.</p><button className="phsar-primary" onClick={saveOrder}>Save service request</button></>}</>}
 </>}
 </section>;
}
