import React,{createContext,useContext,useMemo,useState} from 'react';
import {evidenceUrl} from '../Fin-check/complete-entry';
import {ORDERS,assess} from '../Fin-check/fincheck-model';
import {useNarrativeTranslation} from '../useNarrativeTranslation';
const verdict=m=>Math.abs(Number(m.actual)-Number(m.spec))<=Number(m.tol)+1e-8;
const Badge=({value})=><span className={`qs-badge ${/FAIL|HOLD|Non-conform/i.test(value)?'hold':''}`}>{value||'Not recorded'}</span>;
const NarrativeContext=createContext(value=>value);
function Table({columns,rows}){const showNote=useContext(NarrativeContext);return <div className="qs-scroll"><table><thead><tr>{columns.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((v,j)=><td key={j}>{showNote(v??'Not recorded')}</td>)}</tr>)}</tbody></table>{!rows.length&&<p>No entries recorded for this section.</p>}</div>;}
function Section({title,children}){return <section className="qs-inspection-section"><h3>{title}</h3>{children}</section>;}
function FullReport({record:r}){
 const p=r.payload||{},o=p.orderInfo||ORDERS.find(x=>x.id===p.order)||{},findings=p.findings||[],measurements=p.measurements||[],setup=p.setup||{},checks=p.checks||{};
 let result;try{result=assess({...p,findings,measurements,checks},setup);}catch{result={technical:'PENDING',measurement:measurements.length?(measurements.every(verdict)?'PASS':'FAIL'):'PENDING',defect:'PENDING',counts:{},reasons:['Sampling setup is incomplete.']};}
 const sizes=[...new Set(measurements.map(m=>m.size))],points=[...new Set(measurements.map(m=>m.point))],byPiece=new Map();for(const m of measurements){const k=`${m.size}/${m.piece}`;byPiece.set(k,(byPiece.get(k)??true)&&verdict(m));}
 const summary=new Map();for(const f of findings){const k=`${f.code}|${f.location}|${f.severity}`;summary.set(k,(summary.get(k)||0)+Number(f.count||1));}
 const attachments=p.attachments||[],pos=p.skuDetails||(o.pos||[]).map(([po,qty])=>({po,qty,cartons:p.cartons}));
 const photoEvidence=attachments.filter(a=>a.type?.startsWith('image/')&&evidenceUrl(a,r.module||'fin-check'));
 const notes=useMemo(()=>[
  p.notes,p.review?.comment,p.review?.delegation,
  ...pos.map(x=>x.comment),...findings.map(f=>f.observation),
  ...Object.values(p.checkEvidence||{}).map(x=>x?.note),
  ...attachments.map(a=>a.caption),
  ...(r.amendments||[]).flatMap(a=>[a.reason,a.note]),
 ].filter(value=>typeof value==='string'&&value.trim()),[r]);
 const narrative=useNarrativeTranslation(notes,!p.example),noteSet=new Set(notes);
 const showNote=value=>noteSet.has(value)?narrative.render(value):value;
 return <NarrativeContext.Provider value={showNote}><article className="qs-inspection-document" aria-label="Full inspection report">
 {narrative.state==='loading'&&<p>Translating report notes…</p>}{narrative.state==='unavailable'&&<p>Note translation unavailable; original notes are shown.</p>}
 <header className="qs-inspection-heading"><div><small>YQMS · {p.stage||'FINAL INSPECTION'}</small><h2>INSPECTION REPORT</h2><p>Applicant: {o.factory||'Factory / site not recorded'} · {p.kind||'First inspection'}</p></div><div><strong>{r.buyer||'Buyer not recorded'}</strong><p>Report number: {r.id}</p><p>Report date: {p.date||String(r.at).slice(0,10)}</p><small>{p.example?'Fictional training inspection':'Recorded floor inspection'}</small></div></header>
 <div className="qs-report-cover"><div className="qs-report-cover-photos">{photoEvidence.slice(0,2).map((a,i)=><figure key={a.reference||i}><img src={evidenceUrl(a,r.module||'fin-check')} alt={a.caption||a.category}/><figcaption>{a.caption||a.category}</figcaption></figure>)}{!photoEvidence.length&&<div className="qs-report-photo-empty">Product and unit packing photos appear here when attached from the floor pad.</div>}</div><dl>{[['Description',o.product],['Buyer',r.buyer],['Factory',o.factory],['PO',pos.map(x=>x.po).filter(Boolean).join(', ')],['Style',r.style],['Colour',o.colour],['Inspector',r.inspector],['Inspection place',r.line]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value||'Not recorded'}</dd></div>)}</dl></div>
 <Section title="Inspection conclusion"><div className="qs-report-conclusion"><p><strong>Inspection result</strong><Badge value={result.technical}/></p><p><strong>Management disposition</strong><Badge value={r.status}/></p><p><strong>Checked / defective pieces</strong><span>{r.checked} / {result.counts.total??r.rejected}</span></p><p><strong>Report scope</strong><span>{pos.length} PO lines · {p.cartons||'Cartons not recorded'}</span></p></div><p>{p.example?'Fictional training data; no production approval is implied.':'Final release requires the authorised management decision recorded in DR.'}</p></Section>
 <div className="qs-report-results">{[['Technical result',result.technical],['Measurement',result.measurement],['Defects',result.defect],['Disposition / release',r.status],...(p.externalResult?[['Buyer recorded result',p.externalResult]]:[])].map(([label,value])=><div key={label}><small>{label}</small><Badge value={value}/></div>)}</div>
 <p>Technical results describe the recorded inspection. Independent management review and shipment authority are separate.</p>
 <Section title="1 · Order information"><dl className="qs-report-meta">{[['Order',r.order],['Customer',r.buyer],['Factory',o.factory||'Example factory / recorded site'],['Style',r.style],['Season',o.season],['Lot quantity',o.quantity],['Origin',o.origin||'Not recorded'],['Shipping mode',o.mode||'Not recorded'],['Destination',o.destination],['Product',o.product],['Colour',o.colour],['Fabric content',o.fabric],['Station / line',r.line],['Inspector / QA coordinator',r.inspector],...(p.productionPercent!==undefined?[['Production complete',`${p.productionPercent}%`],['Packing complete',`${p.packingPercent}%`],['Packing list',p.packingListRef],['Readiness reference',p.readinessRef]]:[]),...(p.inspectionAgency?[['Inspection agency',p.inspectionAgency],['External inspector',p.externalInspector],['Buyer report',p.externalReportRef],['Buyer recorded result',p.externalResult]]:[])].map(([label,v])=><div key={label}><dt>{label}</dt><dd>{v??'Not recorded'}</dd></div>)}</dl></Section>
 <Section title="2 · PO lines & carton breakdown"><Table columns={['PO line','Quantity','Selected cartons','Comments']} rows={pos.map(x=>[x.po,x.qty,x.cartons||p.cartons,x.comment||'Recorded inspection scope'])}/></Section>
 <Section title="3 · Colour / size breakdown & SKU details">{p.sizeBreakdown?.length?<Table columns={['Colour','Size','Quantity']} rows={p.sizeBreakdown.map(x=>[x.colour,x.size,x.qty])}/>:<p>{o.colour} · {o.sizes||'No size allocation recorded'}</p>}<Table columns={['SKU','PO line','Colour','Ex-factory','Buyer delivery','Quantity']} rows={pos.map(x=>[x.sku,x.po,x.colour||o.colour,x.exFactory,x.buyerDelivery,x.qty])}/></Section>
 <Section title="4 · Defect summary & garment locations"><Table columns={['Defect','Garment location','Severity','Events']} rows={[...summary].map(([k,n])=>[...k.split('|'),n])}/><Table columns={['Piece','Defect','Location','Severity','Observation']} rows={findings.map(f=>[f.piece,f.code,f.location,f.severity,f.observation||'—'])}/><p>{findings.length} defect events · {result.counts.total??r.rejected} distinct defective pieces. Each piece is counted at its highest severity.</p><div className="qs-location-grid">{[...new Set(findings.map(f=>f.location))].map(location=><div key={location}><strong>{location}</strong><span>{findings.filter(f=>f.location===location).length} recorded events</span><small>{findings.filter(f=>f.location===location).map(f=>`Piece ${f.piece}: ${f.code}`).join(' · ')}</small></div>)}</div></Section>
 <Section title="5 · Sampling & AQL result"><p>{setup.plan||'Plan not recorded'} · revision {setup.revision||'—'} · {setup.level||'Level not recorded'} · code letter {setup.letter||'—'}</p><Table columns={['Lot quantity','Planned sample','Actually inspected','Plan confirmed']} rows={[[o.quantity,setup.sample,r.checked,p.planConfirmed?'Yes':'No']]}/><Table columns={['Severity','AQL label','Defective pieces','Ac / Re','Result']} rows={['Minor','Major','Critical'].map(s=>{const n=result.counts[s],ac=setup[s.toLowerCase()+'Ac'];return [s,setup[s.toLowerCase()+'Aql'],n,ac===undefined?'Not recorded':`${ac} / ${Number(ac)+1}`,<Badge value={ac===undefined?'PENDING':n>ac?'FAIL':'PASS'}/>];})}/><p>Limits belong to this saved buyer plan. Example plans are illustrative and do not replace an approved buyer sampling table.</p></Section>
 <Section title="6 · Buyer-spec measurement summary"><div className="qs-report-results">{[['Readings',measurements.length],['Outside tolerance',measurements.filter(m=>!verdict(m)).length],['Within tolerance',measurements.length?`${(100*measurements.filter(verdict).length/measurements.length).toFixed(1)}%`:'—'],['Pieces passing all readings',`${[...byPiece.values()].filter(Boolean).length} / ${byPiece.size}`]].map(([k,v])=><div key={k}><small>{k}</small><strong>{v}</strong></div>)}</div><Table columns={['Configuration / size','Readings','Failed readings','Result']} rows={sizes.map(size=>{const ms=measurements.filter(m=>m.size===size);return [size,ms.length,ms.filter(m=>!verdict(m)).length,<Badge value={ms.every(verdict)?'PASS':'FAIL'}/>];})}/><h4>Measurement matrix · actual value / deviation</h4><Table columns={['Point of measure',...sizes]} rows={points.map(point=>[point,...sizes.map(size=><div className="qs-reading-cell">{measurements.filter(m=>m.point===point&&m.size===size).map((m,i)=><span className={verdict(m)?'within':'outside'} key={i}>#{m.piece}: {m.actual} {m.unit||'in'} ({(m.actual-m.spec)>=0?'+':''}{(m.actual-m.spec).toFixed(3)})<small>Spec {m.spec} ±{m.tol}</small></span>)}</div>)])}/><details><summary>View every individual reading and tolerance</summary><Table columns={['Point','Size','Piece','Spec','Actual','Deviation','Tolerance','Unit','Result']} rows={measurements.map(m=>[m.point,m.size,m.piece,m.spec,m.actual,(m.actual-m.spec).toFixed(3),`±${m.tol}`,m.unit||'in',<Badge value={verdict(m)?'PASS':'FAIL'}/>])}/></details></Section>
 <Section title="7 · Buyer checklist"><p>Order type: {p.orderType||'Not recorded'} · Approved sample available: {p.sampleAvailable||'Not recorded'}</p><Table columns={['Check','Result','Observation / N/A reason','Evidence reference']} rows={Object.entries(checks).map(([k,v])=>[k,<Badge value={v}/>,p.checkEvidence?.[k]?.note||'—',p.checkEvidence?.[k]?.reference||'—'])}/><p>N/A explanation / observations: {showNote(p.notes)||'None recorded'}</p></Section>
 <Section title="8 · Visual evidence, photos & supporting documents"><p>Carton dimensions: {p.cartonDimensions||'Not recorded'} · Gross weight: {p.cartonWeight||'Not recorded'} kg<br/>Approved sample: {p.approvedSampleRef||'Not recorded'} · Metal detection: {p.metalDetectionRef||'Not recorded'}</p><p>Evidence references: {p.evidence||'No evidence reference recorded'}</p><div className="qs-attachment-grid">{attachments.map((a,i)=>{const url=evidenceUrl(a,r.module||'fin-check');return <article key={i}><strong>{a.category}</strong>{url&&a.type?.startsWith('image/')&&<a href={url} target="_blank" rel="noreferrer"><img src={url} alt={a.caption||a.category} style={{width:'100%',maxHeight:200,objectFit:'contain'}}/></a>}{url?<a href={url} target="_blank" rel="noreferrer">View {a.reference}</a>:<code>{a.reference}</code>}<p>{showNote(a.caption)}</p><small>{a.status}</small></article>;})}</div>{!attachments.length&&<p>Retained photo, laboratory and packing references are shown above. No files have been attached to this record.</p>}<p>Confidential photos and personal details from the supplied reports are not published. Example reference cards do not claim that a file exists.</p></Section>
 <Section title="9 · Containment, correction & linked reinspection"><Table columns={['Held quantity','Hold location','Correction / follow-up','Parent inspection']} rows={[[p.holdQty||0,p.holdLocation||'None recorded',p.notes||'None recorded',p.parent||'First inspection']]}/>{result.reasons.length>0&&<ul>{result.reasons.map((reason,i)=><li key={i}>{reason}</li>)}</ul>}</Section>
 <Section title="10 · Management review & report amendment history"><p>{p.review?<>{p.review.reviewer} · {showNote(p.review.comment)} · {showNote(p.review.delegation)}</>:'Independent release review has not been recorded.'}</p><Table columns={['When','Reviewer','Report','Reason','Revised checked / defective','Evidence / note']} rows={(r.amendments||[]).map(a=>[new Date(a.at).toLocaleString(),`${a.name} · ${a.employeeId}`,a.report,a.reason,`${a.checked} / ${a.rejected}`,a.note])}/><p>This full report displays original inspection measurements and findings. Management changes are recorded separately and applied to the summary reports below.</p></Section>
 </article></NarrativeContext.Provider>;
}
export default function InspectionReports({records,selectedId,onSelect,onPrint}){const [selected,S]=useState(''),[q,Q]=useState('');const list=records.filter(r=>`${r.id} ${r.order} ${r.style} ${r.status}`.toLowerCase().includes(q.toLowerCase())),record=list.find(r=>r._id===(selectedId??selected))||list[0];return <section className="qs-card qs-inspection-report-wrap"><div className="qs-toolbar"><div><h2>Final inspection reports</h2><p>Select a saved floor inspection to view its full report, evidence, measurements, packing scope and management decision.</p></div><input aria-label="Search full inspection reports" placeholder="Order, report, style or result" value={q} onChange={e=>Q(e.target.value)}/></div><div className="qs-report-actions"><label>Inspection report<select aria-label="Select full inspection report" value={record?._id||''} onChange={e=>{S(e.target.value);onSelect?.(e.target.value);}}>{list.map(r=><option key={r._id} value={r._id}>{r.id} · {r.order} · {r.status}</option>)}</select></label>{record&&<button type="button" className="qs-primary" onClick={onPrint||(()=>window.print())}>Print / save report PDF</button>}</div>{record?<FullReport record={record}/>:<p>No saved inspection is available yet.</p>}</section>;}
